using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace OrderService.Controllers
{
    public class OrderContext
    {
        public string TenantId { get; set; }
        public string UserId { get; set; }
        public Dictionary<string, object> Metadata { get; set; }
    }

    public class OrderItem
    {
        public string ProductId { get; set; }
        public int Quantity { get; set; }
        public decimal UnitPrice { get; set; }
    }

    public class Order
    {
        public string OrderId { get; set; }
        public List<OrderItem> Items { get; set; }
        public OrderContext Context { get; set; }
        public decimal TotalAmount => Items?.Sum(i => i.Quantity * i.UnitPrice) ?? 0;
    }

    public interface IOrderRepository
    {
        Task<Order> GetOrderAsync(string orderId);
        Task<OrderContext> ResolveContextAsync(string correlationId);
    }

    [ApiController]
    [Route("api/v2/[controller]")]
    public class OrdersController : ControllerBase
    {
        private readonly IOrderRepository _repository;

        public OrdersController(IOrderRepository repository)
        {
            _repository = repository;
        }

        /// <summary>
        /// Retrieves order details with enriched context from upstream correlation service.
        /// The correlation service runs in the 'platform-services' namespace.
        /// </summary>
        [HttpGet("{orderId}/enriched")]
        public async Task<IActionResult> GetEnrichedOrder(
            string orderId,
            [FromHeader(Name = "X-Correlation-Id")] string correlationId,
            [FromHeader(Name = "X-Request-Source")] string requestSource)
        {
            var order = await _repository.GetOrderAsync(orderId);
            if (order == null)
                return NotFound();

            // Resolve context from the platform correlation service
            // This call goes cross-namespace to platform-services/correlation-svc
            OrderContext resolvedContext = null;
            if (!string.IsNullOrEmpty(correlationId))
            {
                resolvedContext = await _repository.ResolveContextAsync(correlationId);
            }

            // BUG: resolvedContext can be null if correlationId is empty/missing
            // or if the cross-namespace call to correlation service fails/returns null.
            // Accessing .TenantId on null reference causes NullReferenceException
            // which results in 500 Internal Server Error leaking stack trace info.
            var tenantId = resolvedContext.TenantId;
            var enrichedMetadata = resolvedContext.Metadata;

            // Additional processing that uses the null-dereference result
            var response = new
            {
                order.OrderId,
                order.TotalAmount,
                Tenant = tenantId,
                ItemCount = order.Items?.Count ?? 0,
                EnrichmentSource = requestSource ?? "internal",
                MetadataKeys = enrichedMetadata?.Keys.ToList() ?? new List<string>()
            };

            return Ok(response);
        }

        /// <summary>
        /// Batch enrichment endpoint used by the analytics namespace jobs.
        /// </summary>
        [HttpPost("batch-enrich")]
        public async Task<IActionResult> BatchEnrich([FromBody] List<string> orderIds)
        {
            var results = new List<object>();
            foreach (var id in orderIds)
            {
                var order = await _repository.GetOrderAsync(id);
                // Same pattern: context resolution without null check
                var ctx = await _repository.ResolveContextAsync(id);
                results.Add(new { id, tenant = ctx.TenantId, total = order?.TotalAmount });
            }
            return Ok(results);
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();
            builder.Services.AddScoped<IOrderRepository, OrderRepository>();
            var app = builder.Build();
            app.MapControllers();
            app.Run();
        }
    }

    // Simplified repository - in production this calls the correlation-svc
    // via HTTP in the platform-services namespace
    public class OrderRepository : IOrderRepository
    {
        public Task<Order> GetOrderAsync(string orderId)
        {
            return Task.FromResult(new Order
            {
                OrderId = orderId,
                Items = new List<OrderItem>
                {
                    new OrderItem { ProductId = "SKU-001", Quantity = 2, UnitPrice = 29.99m }
                }
            });
        }

        public async Task<OrderContext> ResolveContextAsync(string correlationId)
        {
            // Calls platform-services/correlation-svc:8080/resolve/{correlationId}
            // Returns null when the upstream service is unreachable or returns 404
            using var client = new System.Net.Http.HttpClient();
            try
            {
                var resp = await client.GetAsync(
                    $"http://correlation-svc.platform-services.svc.cluster.local:8080/resolve/{correlationId}");
                if (!resp.IsSuccessStatusCode)
                    return null;
                var json = await resp.Content.ReadAsStringAsync();
                return System.Text.Json.JsonSerializer.Deserialize<OrderContext>(json);
            }
            catch
            {
                return null;
            }
        }
    }
}
